const XLSX = require('xlsx');
const wb = XLSX.readFile('/workspace/testbed/data/order_summary.xlsx');
const data = XLSX.utils.sheet_to_json(wb.Sheets['Orders']);

// Overall stats
const total = data.length;
const confirmed = data.filter(r => r.Status === 'confirmed');
const cancelled = data.filter(r => r.Status === 'cancelled');
const totalRevenue = confirmed.reduce((s,r) => s + r['Total Paid'], 0);
const cancelledValue = cancelled.reduce((s,r) => s + r['Total Paid'], 0);

// By customer (confirmed only)
const byCust = {};
confirmed.forEach(r => {
  if (!byCust[r.Customer]) byCust[r.Customer] = { orders: 0, spent: 0 };
  byCust[r.Customer].orders++;
  byCust[r.Customer].spent += r['Total Paid'];
});

// Top products
const prodCount = {};
confirmed.forEach(r => {
  r.Items.split(', ').forEach(i => { prodCount[i] = (prodCount[i]||0) + 1; });
});
const topProds = Object.entries(prodCount).sort((a,b)=>b[1]-a[1]);

console.log('=== SUMMARY ===');
console.log('Total orders:', total);
console.log('Confirmed:', confirmed.length, '| Cancelled:', cancelled.length);
console.log('Revenue (confirmed):', totalRevenue);
console.log('Cancelled value:', cancelledValue);
console.log('Avg order value (confirmed):', (totalRevenue/confirmed.length).toFixed(2));
console.log();
console.log('=== BY CUSTOMER (confirmed) ===');
Object.entries(byCust).sort((a,b)=>b[1].spent-a[1].spent).forEach(([c,v]) => {
  console.log(c + ': ' + v.orders + ' orders, \$' + v.spent);
});
console.log();
console.log('=== TOP PRODUCTS ===');
topProds.forEach(([p,c]) => console.log(c + 'x  ' + p));

// Date range
const dates = [...new Set(data.map(r=>r.Date))].sort();
console.log();
console.log('Date range:', dates.join(', '));
"

const nodemailer = require("nodemailer");
const fs = require("fs");

// Read the email body (strip the To/Subject header lines)
const raw = fs.readFileSync("/workspace/email_draft_order_summary.md", "utf-8");
const lines = raw.split("\n");
const body = lines.slice(2).join("\n").trim(); // skip To: and Subject: lines

// Configure transporter — adapt these to your SMTP provider:
//   For Gmail:  host: "smtp.gmail.com", port: 465, secure: true
//   For Outlook: host: "smtp.office365.com", port: 587
//   For SendGrid: host: "smtp.sendgrid.net", port: 587
//   For a local relay: host: "localhost", port: 25
const transporter = nodemailer.createTransport({
  host: process.env.SMTP_HOST || "localhost",
  port: parseInt(process.env.SMTP_PORT || "25"),
  secure: process.env.SMTP_SECURE === "true",
  // Uncomment and set if your SMTP server requires authentication:
  // auth: {
  //   user: process.env.SMTP_USER,
  //   pass: process.env.SMTP_PASS,
  // },
  tls: { rejectUnauthorized: false },
  connectionTimeout: 10000,
});

const mailOptions = {
  from: process.env.SMTP_FROM || "orders@example.com",
  to: "bob@example.com",
  subject: "Order Summary Report – Sep 2–4, 2026",
  text: body,
};

(async () => {
  try {
    const info = await transporter.sendMail(mailOptions);
    console.log("✅ Email sent successfully!");
    console.log("   Message ID:", info.messageId);
    console.log("   Response:", info.response);
  } catch (err) {
    console.error("❌ Failed to send email:", err.message);
    console.error();
    console.error("To send this email, set these environment variables and re-run:");
    console.error("  export SMTP_HOST=smtp.gmail.com      # your SMTP server");
    console.error("  export SMTP_PORT=587                  # SMTP port");
    console.error("  export SMTP_SECURE=false              # true for port 465");
    console.error("  export SMTP_USER=you@gmail.com        # SMTP username");
    console.error("  export SMTP_PASS=your-app-password    # SMTP password");
    console.error("  export SMTP_FROM=you@gmail.com        # sender address");
    console.error("  node /workspace/send_email.js");
    process.exit(1);
  }
})();
